(1778868, 242499, 43405, '<td valign="top">Like a postcard.</td>', 'Like a postcard.', '2005-10-12 07:29:45.000000', NULL, 1),
(1778870, 243040, 31889, '<td valign="top">Should try and use the max allowable screen estate.  Smallish shots tend to get heavily penalised.  Good luck for the next challenge.</td>', 'Should try and use the max allowable screen estate.  Smallish shots tend to get heavily penalised.  Good luck for the next challenge.', '2005-10-12 07:30:29.000000', NULL, 1),
(1778872, 241818, 43405, '<td valign="top">This should have been a postcard. Beautiful</td>', 'This should have been a postcard. Beautiful', '2005-10-12 07:31:34.000000', NULL, 1),
(1778873, 241440, 31889, '<td valign="top">Congrats in advance on the brown.</td>', 'Congrats in advance on the brown.', '2005-10-12 07:34:08.000000', NULL, 1),
(1778876, 243007, 31889, '<td valign="top">In our dreams...........nice shot!</td>', 'In our dreams...........nice shot!', '2005-10-12 07:41:28.000000', NULL, 1),
