(1788757, 240898, 22046, '<td valign="top">Very dramatic photograph. Using black on the darker half of his face emphasizes the drama here.</td>', 'Very dramatic photograph. Using black on the darker half of his face emphasizes the drama here.', '2005-10-16 23:36:55.000000', NULL, 1),
