(1788765, 242707, 22046, '<td valign="top">One of the best of the "my pride and joy" photos. I love her direct look into the camera. Also the composition is great pulling the eye to her open and beautiful young face.</td>', 'One of the best of the "my pride and joy" photos. I love her direct look into the camera. Also the composition is great pulling the eye to her open and beautiful young face.', '2005-10-16 23:38:27.000000', NULL, 1),
(1788768, 242267, 22046, '<td valign="top">One of my two favorite "pride and joy" photos. I like how your daughter / granddaughter is offset and the white background works very well with her coloring. Beautiful portrait.</td>', 'One of my two favorite "pride and joy" photos. I like how your daughter / granddaughter is offset and the white background works very well with her coloring. Beautiful portrait.', '2005-10-16 23:39:24.000000', NULL, 1),
(1788773, 242501, 22046, '<td valign="top">Great expression of pride and joy on this girl''s face. Good composition too. I usually don''t go for bathroom images but this one is different from most. It''s about the child''d delight in her prowess rather than about the bathroom per se. Good one.</td>', 'Great expression of pride and joy on this girl''s face. Good composition too. I usually don''t go for bathroom images but this one is different from most. It''s about the child''d delight in her prowess rather than about the bathroom per se. Good one.', '2005-10-16 23:40:45.000000', NULL, 1),
(1788775, 242707, 45596, '<td valign="top">Nice picture, but lacks originality.</td>', 'Nice picture, but lacks originality.', '2005-10-16 23:40:53.000000', NULL, 1),
