(1788786, 243114, 22046, '<td valign="top">These boots speak volumes about the pride of hard work well done. Excellent use of an icon.</td>', 'These boots speak volumes about the pride of hard work well done. Excellent use of an icon.', '2005-10-16 23:43:32.000000', NULL, 1),
