INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1798700, 242582, 42792, '<td valign="top">This is such a startling stare you''ve captured and for that alone, I think it works great as an image!  Very nice overall.  It probably scored low because viewers couldn''t understand how it represents Pride.  Maybe you could explain a little.  Altho'' voting is over, it''ll open up our minds a little as to how different people see pride. :)</td>', 'This is such a startling stare you''ve captured and for that alone, I think it works great as an image!  Very nice overall.  It probably scored low because viewers couldn''t understand how it represents Pride.  Maybe you could explain a little.  Altho'' voting is over, it''ll open up our minds a little as to how different people see pride. :)', '2005-10-20 15:22:21.000000', NULL, 0),
